import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var tracks = React.useState(true), timer = React.useRef(null);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    function change(state) { return function (event) { state[1](event.target.checked); }; }
    return <div className="dsswitch-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <S.DsSwitch label={'Показывать треки'} checked={tracks[0]} onChange={change(tracks)}/>
    <p className={'result'} role={'status'}>
    {tracks[0] ? 'Треки отображаются на карте.' : 'Треки скрыты.'}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsswitch-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsswitch-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsswitch-example p{margin:0}\n.dsswitch-example section+section{margin-top:24px}\n.dsswitch-example .result{margin:12px 0 0;color:var(--ds-fg-subtle)}";

export { App as Example };

