import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var saved = React.useState(false), busy = React.useState(false), fail = React.useState(false), message = React.useState(''), timer = React.useRef(null);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    function save(event) {
        var previous = saved[0];
        saved[1](event.target.checked);
        busy[1](true);
        message[1]('');
        timer.current = setTimeout(function () {
            busy[1](false);
            if (fail[0]) {
                saved[1](previous);
                message[1]('Не удалось сохранить настройку. Попробуйте ещё раз.');
            }
            else
                message[1]('Настройка сохранена.');
        }, 1800);
    }
    return <div className="dsswitch-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'stack'}>
    <S.DsSwitch label={'Автоматическое обновление карты'} description={'Настройка сохраняется на сервере'} checked={saved[0]} loading={busy[0]} onChange={save}/>
    <S.DsCheckbox label={'Имитировать ошибку сохранения'} state={fail[0] ? 'checked' : 'unchecked'} disabled={busy[0]} onChange={function (value) { fail[1](value === 'checked'); }}/>
    </div>
    <p className={'result'} role={'status'}>
    {message[0]}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsswitch-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsswitch-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsswitch-example p{margin:0}\n.dsswitch-example section+section{margin-top:24px}\n.dsswitch-example .stack{display:flex;flex-direction:column;gap:16px;align-items:flex-start}\n.dsswitch-example .result{margin:12px 0 0;color:var(--ds-fg-subtle)}";

export { App as Example };
